print('--- compare forms at lam=0.3/0.5')
def predw(lam, wfun):
    out=[];cache={}
    for s,tt in zip(sets,t):
        if s not in cache:
            n=len(s); wt=wfun(n)
            ll_=(E[:,np.array(s)-1]*wt).sum(1)
            pr=np.r_[np.full(NR,np.log(lam/NR)), np.full(len(M)-NR, np.log((1-lam)/100**2))]
            lj=pr+ll_; post=np.exp(lj-logsumexp(lj)); cache[s]=post@M
        out.append(cache[s][tt-1])
    return np.clip(np.array(out),1e-6,1-1e-6)
for lam in [0.2,0.3,0.5]:
  for c in [0.3,0.5,0.7]:
    print(lam,c,'temper',round(ll(predw(lam,lambda n:np.full(n,c))),1),
      'recency',round(ll(predw(lam,lambda n:c**(n-1-np.arange(n)))),1),
      'primacy',round(ll(predw(lam,lambda n:c**np.arange(n))),1),
      'cap', round(ll(predw(lam,lambda n:np.full(n,min(1,(1+ (c*3))/n)))),1))
